/**
 * Typed CSS-module declaration (same hand-authored convention as basalt-ui's own
 * `content/article-card.module.css.d.ts`) — named string props, not an index signature, so dot
 * access stays verbatim under `noPropertyAccessFromIndexSignature`.
 */
declare const classes: {
  readonly anchorReset: string
  readonly tree: string
  readonly item: string
  readonly group: string
  readonly row: string
  readonly chevron: string
}
export default classes
